mapper.select:
SELECT th.TR_SNO ,th.MEMBER_NO ,th.TR_DT ,th.TR_GB_CD ,th.TR_METHOD_GB_CD ,th.TR_DY ,th.ORG_NO ,th.BRCH_NO ,th.TR_PT ,th.BEF_PT ,th.AFR_PT ,th.ORGL_TR_SNO ,th.REG_USER_ID ,th.REG_DT ,th.LAST_MOD_USER_ID ,th.LAST_MOD_DT FROM T_TR_HIST th
INNER JOIN T_TR_HIST_DETAIL thd ON thd.MEMBER_NO = #{memberNo} AND thd.CONT_NO = #{contNo} AND thd.TR_SNO = th.TR_SNO
WHERE th.MEMBER_NO = #{memberNo}
AND th.TR_GB_CD = #{trGbCd}
AND th.TR_SNO = #{trSno}
AND th.ORGL_TR_SNO = #{orglTrSno}
ORDER BY th.TR_DT DESC, th.TR_SNO DESC LIMIT 1

SELECT
COUNT(th.TR_SNO)
FROM T_TR_HIST th
WHERE 1 = 1

    AND th.MEMBER_NO = #{memberNo}


    AND th.ORG_NO = #{orgNo}


    AND th.BRCH_NO = #{brchNo}


    AND (th.TR_DT  >=  #{startDt} AND th.TR_DT  <  #{endDt})


    AND th.TR_GB_CD = #{trGbCd}


    AND th.TR_GB_CD IN

        #{code}



  AND th.TR_METHOD_GB_CD = #{trMethodGbCd}


    AND th.ORGL_TR_SNO = #{orglTrSno}

SELECT T.ROW_NUM AS ROW_NUM ,T.* FROM ( SELECT ROW_NUMBER() OVER(ORDER BY th.TR_SNO) ROW_NUM ,th.TR_SNO ,th.MEMBER_NO ,th.TR_DT ,th.TR_GB_CD ,th.TR_METHOD_GB_CD ,th.TR_DY ,th.ORG_NO ,th.BRCH_NO ,th.TR_PT ,th.BEF_PT ,th.AFR_PT ,th.ORGL_TR_SNO ,th.REG_USER_ID ,th.REG_DT ,th.LAST_MOD_USER_ID ,th.LAST_MOD_DT FROM T_TR_HIST th WHERE 1 = 1
AND th.MEMBER_NO = #{memberNo}
AND th.ORG_NO = #{orgNo}
AND th.BRCH_NO = #{brchNo}
AND (th.TR_DT >= #{startDt} AND th.TR_DT < #{endDt})
AND th.TR_GB_CD = #{trGbCd}
AND th.TR_GB_CD IN
#{code}
AND th.TR_METHOD_GB_CD = #{trMethodGbCd}
AND th.ORGL_TR_SNO = #{orglTrSno}
ORDER BY th.TR_DT DESC, th.TR_SNO DESC ) T
WHERE T.ROW_NUM BETWEEN #{startIndex} AND #{endIndex}
